CREATE TABLE "OfficeMessage" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "officeId" UUID NOT NULL, "senderId" UUID NOT NULL, "subject" TEXT NOT NULL DEFAULT '', "body" TEXT NOT NULL, "isAnnouncement" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "OfficeMessage_pkey" PRIMARY KEY ("id"), CONSTRAINT "OfficeMessage_officeId_id_key" UNIQUE ("officeId", "id"), CONSTRAINT "OfficeMessage_officeId_fkey" FOREIGN KEY ("officeId") REFERENCES "Office"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "OfficeMessage_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "OfficeMessage_officeId_createdAt_idx" ON "OfficeMessage"("officeId", "createdAt");
CREATE TABLE "MessageRecipient" ("messageId" UUID NOT NULL, "userId" UUID NOT NULL, "readAt" TIMESTAMPTZ(3), CONSTRAINT "MessageRecipient_pkey" PRIMARY KEY ("messageId", "userId"), CONSTRAINT "MessageRecipient_messageId_fkey" FOREIGN KEY ("messageId") REFERENCES "OfficeMessage"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "MessageRecipient_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "MessageRecipient_userId_readAt_idx" ON "MessageRecipient"("userId", "readAt");
